<?php
$pagination = $pagination ?? ['page' => 1, 'pages' => 1, 'page_size' => 15, 'total' => 0];
$filters = $filters ?? [];
$pageSize = (int) ($pagination['page_size'] ?? 15);
$pageUrl = static function (int $page) use ($filters, $pageSize): string {
    $query = array_filter(['search' => $filters['search'] ?? '', 'status' => $filters['status'] ?? '', 'page_size' => $pageSize, 'page' => $page], static fn ($value) => $value !== '' && $value !== null);
    return current_url() . '?' . http_build_query($query);
};
?>
<div class="card-footer d-flex flex-wrap justify-content-between align-items-center"><form method="get" action="<?= current_url() ?>" class="form-inline mb-2 mb-md-0" aria-label="Page size"><input type="hidden" name="search" value="<?= esc($filters['search'] ?? '') ?>"><input type="hidden" name="status" value="<?= esc($filters['status'] ?? '') ?>"><label class="small mr-2" for="farmassist-page-size">Rows per page</label><select class="custom-select custom-select-sm" id="farmassist-page-size" name="page_size" onchange="this.form.submit()"><?php foreach ([10,15,25,50] as $size): ?><option value="<?= $size ?>" <?= (int) ($pagination['page_size'] ?? 15) === $size ? 'selected' : '' ?>><?= $size ?></option><?php endforeach; ?></select></form><nav aria-label="Review queue pagination"><span class="small text-muted mr-3">Page <?= esc((string) ($pagination['page'] ?? 1)) ?> of <?= esc((string) ($pagination['pages'] ?? 1)) ?> (<?= esc((string) ($pagination['total'] ?? 0)) ?> total)</span><a class="btn btn-sm btn-outline-secondary <?= ($pagination['page'] ?? 1) <= 1 ? 'disabled' : '' ?>" href="<?= ($pagination['page'] ?? 1) > 1 ? esc($pageUrl(($pagination['page'] ?? 1) - 1)) : '#' ?>" aria-label="Previous page">Previous</a> <a class="btn btn-sm btn-outline-secondary <?= ($pagination['page'] ?? 1) >= ($pagination['pages'] ?? 1) ? 'disabled' : '' ?>" href="<?= ($pagination['page'] ?? 1) < ($pagination['pages'] ?? 1) ? esc($pageUrl(($pagination['page'] ?? 1) + 1)) : '#' ?>" aria-label="Next page">Next</a></nav></div>
